{"files":[{"path":"src/limits.mjs","content":"export function cleanBatch(input) {
  if (!Array.isArray(input)) {
    throw new TypeError("expected array");
  }

  const values = [];
  const errors = [];

  for (let index = 0; index < input.length; index += 1) {
    const item = input[index];

    if (typeof item !== "string") {
      errors.push({ index, reason: "not a string" });
      continue;
    }

    const trimmed = item.trim();

    if (trimmed.length === 0) {
      errors.push({ index, reason: "empty string" });
      continue;
    }

    if (trimmed.length > 20) {
      errors.push({ index, reason: "string exceeds 20 characters" });
      continue;
    }

    values.push(trimmed);
  }

  return { values, errors };
}
